import React, { useState, useCallback } from 'react';

const App = () => {
  const [count, setCount] = useState(0);

  const incrementRegular = () => {
    setCount(count + 1);
  };

  const incrementMemoized = useCallback(() => {
    setCount(count + 1);
  }, [count]);

  return (
    <div>
      {/* Render two Child components here */}
    </div>
  );
};

const Child = ({ increment }) => {
  console.log('Child rendered');
  return (
    <button onClick={increment}>
      Increment
    </button>
  );
};

export default App;
